-- Módulo 47: vales e intervalo manual de odómetro; sin movimientos de inventario.
CREATE TABLE "ValesCombustible" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Codigo" varchar(20) NOT NULL CHECK ("Codigo" = btrim("Codigo") AND length("Codigo") > 0),
    "Placa" varchar(20) NOT NULL CHECK ("Placa" = upper(btrim("Placa")) AND length("Placa") > 0),
    "Estacion" varchar(150) NOT NULL CHECK ("Estacion" = btrim("Estacion") AND length("Estacion") > 0),
    "FechaCarga" timestamptz NOT NULL,
    "TipoCombustible" varchar(15) NOT NULL CHECK ("TipoCombustible" IN ('Diesel','Gasolina')),
    "Litros" numeric(10,3) NOT NULL CHECK ("Litros" BETWEEN 0.001 AND 9999999.999),
    "PrecioLitro" numeric(10,3) NOT NULL CHECK ("PrecioLitro" BETWEEN 0.001 AND 9999999.999),
    "Moneda" varchar(3) NOT NULL CHECK ("Moneda" ~ '^[A-Z]{3}$'),
    "OdometroInicial" integer NOT NULL CHECK ("OdometroInicial" BETWEEN 0 AND 999999999),
    "OdometroFinal" integer CHECK ("OdometroFinal" BETWEEN 0 AND 999999999 AND "OdometroFinal" > "OdometroInicial"),
    "Observaciones" varchar(500),
    "Estado" varchar(15) NOT NULL DEFAULT 'Borrador',
    "FechaConfirmacion" timestamptz,
    "FechaAnulacion" timestamptz,
    "MotivoAnulacion" varchar(500),
    CONSTRAINT "CK_ValesCombustible_Confirmacion" CHECK ("FechaConfirmacion" IS NULL OR "OdometroFinal" IS NOT NULL),
    CONSTRAINT "CK_ValesCombustible_Estado" CHECK (
        ("Estado" = 'Borrador' AND "FechaConfirmacion" IS NULL AND "FechaAnulacion" IS NULL AND "MotivoAnulacion" IS NULL) OR
        ("Estado" = 'Confirmado' AND "OdometroFinal" IS NOT NULL AND "FechaConfirmacion" IS NOT NULL AND "FechaAnulacion" IS NULL AND "MotivoAnulacion" IS NULL) OR
        ("Estado" = 'Anulado' AND "FechaAnulacion" IS NOT NULL AND "MotivoAnulacion" IS NOT NULL AND length(btrim("MotivoAnulacion")) > 0))
);
CREATE UNIQUE INDEX "IX_ValesCombustible_Codigo" ON "ValesCombustible" (lower(btrim("Codigo")));
